cat > /workspace/harness/argvprobe.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test6_executable';
const lines = readFileSync(process.argv[2], 'utf8').split('\n').filter(l => l.trim() !== '' && !l.startsWith('//'));
for (const l of lines) {
  const c = JSON.parse(l);
  const label = c.label ?? JSON.stringify(c.argv ?? c);
  const argv = (c.argv ?? c).map(s => typeof s === 'string' ? s : String(s));
  const env = c.env ? {...process.env, ...c.env} : process.env;
  const r = spawnSync(EXE, argv, { encoding: 'utf8', maxBuffer: 1<<28, env });
  console.log('=== ' + label);
  console.log('ARGV ' + JSON.stringify(argv.map(a=>a.length>200?a.slice(0,60)+'...<len='+a.length+'>':a)));
  console.log('RC   ' + r.status + (r.signal? ' SIG '+r.signal : ''));
  const trunc = s => s==null? null : (s.length>4000 ? s.slice(0,4000)+'...<TRUNC len='+s.length+'>' : s);
  console.log('OUT  ' + JSON.stringify(trunc(r.stdout)));
  console.log('ERR  ' + JSON.stringify(trunc(r.stderr)));
}
EOF
echo ok

